const EVENT_KEY = 'tour_engine_demo_events';
const PENDING_EVENT_KEY = 'tour_engine_demo_pending_api_events';
const DEFAULT_API_URL = 'http://127.0.0.1:8787';

function getApiUrl() {
  return (import.meta.env?.VITE_TOUR_ENGINE_API_URL || DEFAULT_API_URL).replace(/\/$/, '');
}

export function safeRead(key, fallback) {
  try {
    return JSON.parse(localStorage.getItem(key) || JSON.stringify(fallback));
  } catch {
    return fallback;
  }
}

export function safeWrite(key, value) {
  localStorage.setItem(key, JSON.stringify(value));
}

export function readLocalEvents() {
  return safeRead(EVENT_KEY, []);
}

export function readPendingApiEvents() {
  return safeRead(PENDING_EVENT_KEY, []);
}

function upsertLocalEvent(updatedEvent) {
  const nextEvents = readLocalEvents().map(event => event.id === updatedEvent.id ? updatedEvent : event);
  safeWrite(EVENT_KEY, nextEvents.slice(0, 100));
}

function queuePendingApiEvent(event) {
  const pending = readPendingApiEvents();
  if (!pending.some(item => item.id === event.id)) {
    safeWrite(PENDING_EVENT_KEY, [...pending, event].slice(-100));
  }
}

function removePendingApiEvent(eventId) {
  safeWrite(PENDING_EVENT_KEY, readPendingApiEvents().filter(event => event.id !== eventId));
}

function toApiEvent(event) {
  return {
    id: event.id,
    type: event.type,
    occurredAt: event.createdAt,
    ...event.payload,
    metadata: event.payload
  };
}

async function postEventToApi(event) {
  const apiUrl = getApiUrl();
  const response = await fetch(`${apiUrl}/api/events`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify(toApiEvent(event))
  });

  if (!response.ok) {
    throw new Error(`event_post_failed_${response.status}`);
  }

  return response.json();
}

export function recordLocalEvent(type, payload = {}) {
  const event = {
    id: `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
    type,
    payload,
    createdAt: new Date().toISOString(),
    syncStatus: 'pending'
  };

  const nextEvents = [event, ...readLocalEvents()].slice(0, 100);
  safeWrite(EVENT_KEY, nextEvents);

  postEventToApi(event)
    .then(() => {
      const syncedEvent = { ...event, syncStatus: 'synced' };
      upsertLocalEvent(syncedEvent);
      removePendingApiEvent(event.id);
    })
    .catch(() => {
      const queuedEvent = { ...event, syncStatus: 'queued' };
      upsertLocalEvent(queuedEvent);
      queuePendingApiEvent(queuedEvent);
    });

  return event;
}

export async function syncPendingApiEvents() {
  const pending = readPendingApiEvents();
  const results = [];

  for (const event of pending) {
    try {
      await postEventToApi(event);
      const syncedEvent = { ...event, syncStatus: 'synced' };
      upsertLocalEvent(syncedEvent);
      removePendingApiEvent(event.id);
      results.push({ id: event.id, ok: true });
    } catch (error) {
      results.push({ id: event.id, ok: false, error: error.message });
    }
  }

  return results;
}

export function clearLocalEvents() {
  localStorage.removeItem(EVENT_KEY);
  localStorage.removeItem(PENDING_EVENT_KEY);
}

export function getStorageKey(prefix, id) {
  return `tour_engine_demo_${prefix}_${id}`;
}
